  "src/web/lib/cheatsheet/recipes/tree-view.ts"() {
    "use strict";
    treeView = {
      id: "tree-view",
      title: "\u0414\u0440\u0435\u0432\u043E\u0432\u0438\u0434\u043D\u043E\u0435 \u043F\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043B\u0435\u043D\u0438\u0435",
      description: "\u041D\u0430\u0441\u0442\u0440\u043E\u0438\u0442\u044C \u0434\u0435\u0440\u0435\u0432\u043E \u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0435\u0433\u043E \u0447\u0435\u0440\u0435\u0437 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435",
      sections: ["trees", "views", "actions"],
      md: `
# \u0414\u0440\u0435\u0432\u043E\u0432\u0438\u0434\u043D\u043E\u0435 \u043F\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043B\u0435\u043D\u0438\u0435

## \u0427\u0442\u043E \u0434\u0435\u043B\u0430\u0435\u043C

\u041F\u043E\u043A\u0430\u0437\u0430\u0442\u044C \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u044E \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u0439 \u0432 \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0435 \u2014 \u0441 \u0440\u0430\u0441\u043A\u0440\u044B\u0442\u0438\u0435\u043C \u0443\u0437\u043B\u043E\u0432 \u0438 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u043E\u043C \u043A \u0441\u043F\u0438\u0441\u043A\u0443 \u043E\u0431\u044A\u0435\u043A\u0442\u043E\u0432.

## \u0428\u0430\u0433\u0438

1. \u041E\u043F\u0438\u0448\u0438\u0442\u0435 \u0441\u0432\u044F\u0437\u0438 \`1_n\` \u043C\u0435\u0436\u0434\u0443 \u0443\u0440\u043E\u0432\u043D\u044F\u043C\u0438 \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0438.
2. \u0421\u043E\u0437\u0434\u0430\u0439\u0442\u0435 \`trees[]\` \u0437\u0430\u043F\u0438\u0441\u044C.
3. \u0421\u043E\u0437\u0434\u0430\u0439\u0442\u0435 \`views[type: tree]\` \u2014 \u0432\u0438\u0437\u0443\u0430\u043B\u0438\u0437\u0430\u0446\u0438\u044E \u0434\u0435\u0440\u0435\u0432\u0430.
4. \u0421\u043E\u0437\u0434\u0430\u0439\u0442\u0435 \`action[type: open_tree]\` \u2014 \u0442\u043E\u0447\u043A\u0443 \u0432\u0445\u043E\u0434\u0430.

## 1. \u0421\u0432\u044F\u0437\u0438

\`\`\`yaml
linkages:
  - id: Category_Subcategory
    side1: Category
    side2: Subcategory
    type: 1_n
    nameFrom:
      side1: \u0421\u043E\u0434\u0435\u0440\u0436\u0438\u0442 \u043F\u043E\u0434\u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u0438
      side2: \u0412\u0445\u043E\u0434\u0438\u0442 \u0432 \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u044E
\`\`\`

## 2. \u0414\u0435\u0440\u0435\u0432\u043E

\`\`\`yaml
trees:
  - id: CategoryTree
    type: orderable
    hierarchy:
      entity: Category
      maxInstances: 1
      children:
        - linkage: Category_Subcategory
          entity: Subcategory
\`\`\`

## 3. Tree-view

\`\`\`yaml
views:
  - id: treeCategories
    type: tree
    tree: CategoryTree
    variant: merged    # merged | splitted
    nodeChunkSize: 20
\`\`\`

- \`variant: merged\` \u2014 \u0434\u0435\u0440\u0435\u0432\u043E + \u0441\u043F\u0438\u0441\u043E\u043A \u0432 \u043E\u0434\u043D\u043E\u043C \u043E\u043A\u043D\u0435.
- \`variant: splitted\` \u2014 \u0434\u0432\u0430 \u043E\u043A\u043D\u0430: \u0441\u043B\u0435\u0432\u0430 \u0434\u0435\u0440\u0435\u0432\u043E, \u0441\u043F\u0440\u0430\u0432\u0430 \u0441\u043F\u0438\u0441\u043E\u043A.

## 4. \u0414\u0435\u0439\u0441\u0442\u0432\u0438\u0435

\`\`\`yaml
actions:
  - id: actions_openCategoriesTree
    name: \u0414\u0435\u0440\u0435\u0432\u043E \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u0439
    type: open_tree
    view: treeCategories
\`\`\`

## 5. \u0422\u043E\u0447\u043A\u0430 \u0432\u0445\u043E\u0434\u0430 \u0432 \u043C\u0435\u043D\u044E

\`\`\`yaml
menus:
  - id: menus_categories
    route: /categories
    label: \u041A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u0438
    type: root_menu
    placement: top
    view: treeCategories
\`\`\`

## \u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430

\u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u043C\u0435\u043D\u044E \u2192 \xAB\u041A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u0438\xBB \u2192 \u0434\u0435\u0440\u0435\u0432\u043E \u043E\u0442\u043E\u0431\u0440\u0430\u0436\u0430\u0435\u0442\u0441\u044F. \u0415\u0441\u043B\u0438 \u043D\u0435\u0442 \u2014 \u043F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435, \u0447\u0442\u043E \u0441\u0432\u044F\u0437\u044C \`1_n\` \u043A\u043E\u0440\u0440\u0435\u043A\u0442\u043D\u0430 \u0438 \u0447\u0442\u043E \u0432 \`trees.hierarchy.entity\` \u0443\u043A\u0430\u0437\u0430\u043D\u0430 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044E\u0449\u0430\u044F \u0441\u0443\u0449\u043D\u043E\u0441\u0442\u044C.
`
    };
  }
